import 'package:flutter/cupertino.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import '../../../../Config/Assets/image_png.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';class AuthenticationSplit1 extends StatelessWidget {  const AuthenticationSplit1({super.key});  @override  Widget build(BuildContext context) {    final bool isSmall = context.isSmallScreen;    return Align(      alignment: isSmall ? Alignment.topCenter : Alignment.centerRight,      child: Container(        color: AppColors.backgroundColor,        width: isSmall ? null : 0.5.sw,        child: isSmall            ? buildImageColumInRow(isSmall)            : AspectRatio(                aspectRatio: 1,                child: buildImageColumInRow(isSmall),              ),      ),    );  }  Widget _buildImage(String imagePath,bool isSmall) {     Image images(String imagePath) {      return Image.asset(        imagePath,        fit: BoxFit.contain,      );    }    return isSmall ? images(imagePath):Expanded(child: images(imagePath));  }  Row buildImageColumInRow(bool isSmall) {    Column buildColumn(List<String> imagePaths,bool isSmall) {      return Column(        children: imagePaths.map((path) => _buildImage(path,isSmall)).toList(),      );    }    Widget buildImageColumn(List<String> imagePaths, ) {      return Expanded(        child: buildColumn(imagePaths,isSmall),      );    }    return Row(      children: [        buildImageColumn(            [AppImagesPng.image7, AppImagesPng.image8, AppImagesPng.image9]),        buildImageColumn(            [AppImagesPng.image4, AppImagesPng.image6, AppImagesPng.image5] ),        buildImageColumn(            [AppImagesPng.image1, AppImagesPng.image2, AppImagesPng.image3]),      ],    );  }}